var Q28 = [
  {n:1, q:'El artículo 104.2 de la Constitución establece que una ley orgánica determinará las funciones, principios básicos de actuación y estatutos de:', o:{a:'Las Fuerzas y Cuerpos de Seguridad.', b:'Las Fuerzas y Cuerpos de Seguridad del Estado.', c:'Las Fuerzas y Cuerpos de la Seguridad del Estado y las Policías de las Comunidades Autónomas.', d:'Las Fuerzas y Cuerpos de la Seguridad del Estado, las Policías de las Comunidades Autónomas y las Policías Locales.'}, correct:'b', why:{b:'El art. 104.2 CE establece una reserva de Ley Orgánica para determinar las funciones, principios básicos de actuación y estatutos de las Fuerzas y Cuerpos de Seguridad. En cumplimiento de esta reserva se dictó la LO 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad.'}},
  {n:2, q:'La seguridad pública de acuerdo con el artículo 149.1.29ª de la Constitución es una competencia que corresponde:', o:{a:'Con carácter exclusivo al Estado.', b:'Al Estado y a las Comunidades Autónomas.', c:'Al Estado, a las Comunidades Autónomas y a las Corporaciones Locales.', d:'A las Fuerzas y Cuerpos de Seguridad del Estado.'}, correct:'a', why:{a:'El art. 149.1.29ª CE atribuye al Estado competencia exclusiva en materia de seguridad pública, sin perjuicio de la posibilidad de creación de policías por las CCAA en la forma que se establezca en sus Estatutos en el marco de lo que disponga una ley orgánica.'}},
  {n:3, q:'La Ley Orgánica 2/1986, de 13 de marzo, de Fuerzas y Cuerpos de Seguridad:', o:{a:'Tiene carácter de Ley orgánica en todo su articulado, de acuerdo con lo exigido en el artículo 104 de la Constitución.', b:'Se trata de una Ley ordinaria.', c:'Se trata de una Ley mixta, que solo tiene la consideración de Ley Orgánica respecto de algunos preceptos y de Ley ordinaria respecto de otros.', d:'Tiene carácter de Ley orgánica en todo su articulado, aunque la Constitución no dice nada al respecto.'}, correct:'c', why:{c:'Conforme a la Disposición Final Quinta de la LOFCS, tienen carácter de Ley Orgánica los preceptos contenidos en los Títulos I, III, V y parte del Título II. Otros aspectos no tienen carácter orgánico, por lo que se trata de una Ley mixta.'}},
  {n:4, q:'El mantenimiento de la seguridad pública de acuerdo con el artículo 1 de la LOFCS corresponde:', o:{a:'Al Estado.', b:'Al Gobierno de la Nación.', c:'A las Administraciones Públicas.', d:'Al Estado, a las Comunidades Autónomas y a las Corporaciones Locales.'}, correct:'b', why:{b:'El art. 1 LOFCS dispone: «La seguridad pública es competencia exclusiva del Estado. Su mantenimiento corresponde al Gobierno de la Nación». CCAA y Corporaciones Locales solo participan en su mantenimiento.'}},
  {n:5, q:'Son Fuerzas y Cuerpos de Seguridad:', o:{a:'Las Fuerzas y Cuerpos de Seguridad del Estado.', b:'Las Fuerzas y Cuerpos de Seguridad del Estado y los Cuerpos de Policía dependientes de las Comunidades Autónomas.', c:'Las Fuerzas y Cuerpos de Seguridad del Estado, los Cuerpos de Policía dependientes de las Comunidades Autónomas y los Cuerpos de Policía dependientes de las Corporaciones Locales.', d:'Las Fuerzas y Cuerpos de Seguridad del Estado, los Cuerpos de Policía dependientes de las Comunidades Autónomas, los Cuerpos de Policía dependientes de las Corporaciones Locales y los Vigilantes de Seguridad.'}, correct:'c', why:{c:'El art. 2 LOFCS dispone: «Son Fuerzas y Cuerpos de Seguridad: a) Las FCS del Estado dependientes del Gobierno de la nación, b) Los Cuerpos de Policía dependientes de las CCAA y c) Los Cuerpos de Policía dependientes de las Corporaciones Locales».'}},
  {n:6, q:'De acuerdo con el artículo 3 de la LOFCS los miembros de las Fuerzas y Cuerpos de Seguridad ajustarán su actuación al principio de:', o:{a:'Lealtad institucional.', b:'Cooperación recíproca.', c:'Buena fe.', d:'Jerarquía.'}, correct:'b', why:{b:'El art. 3 LOFCS establece que los miembros de las FCS ajustarán su actuación al principio de cooperación recíproca. La misma exigencia aparece en el art. 12.2 y 3 de la Ley.'}},
  {n:7, q:'¿Quiénes tienen especial obligación de auxiliar y colaborar en todo momento con las Fuerzas y Cuerpos de Seguridad?', o:{a:'Todos los ciudadanos, cualquiera que sea su nacionalidad.', b:'Los ciudadanos españoles mayores de edad.', c:'Las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas al personal y bienes o servicios de titularidad pública o privada.', d:'Cualquier persona física o jurídica.'}, correct:'c', why:{c:'El art. 4 LOFCS dispone que las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas a personal y bienes o servicios de titularidad pública o privada tienen especial obligación de auxiliar o colaborar en todo momento con las FCS.'}},
  {n:8, q:'El código deontológico que vincula a todos los miembros de las Fuerzas y Cuerpos de Seguridad se establece en el artículo 5 del Capítulo II de la LOFCS bajo la rúbrica:', o:{a:'Disposiciones generales.', b:'Principios básicos de actuación.', c:'Disposiciones estatutarias comunes.', d:'Normas generales.'}, correct:'b', why:{b:'La LOFCS establece en su art. 5 los Principios Básicos de Actuación como un verdadero código deontológico que vincula a todos los miembros de las Fuerzas policiales (estatales, autonómicas o locales).'}},
  {n:9, q:'En su actuación profesional, los miembros de las Fuerzas y Cuerpos de Seguridad deberán ajustarse a los principios de:', o:{a:'Coordinación y subordinación.', b:'Jerarquía y coordinación.', c:'Subordinación y jerarquía.', d:'Coordinación y colaboración.'}, correct:'c', why:{c:'El art. 5.1.d) LOFCS dispone que las FCS deberán sujetarse en su actuación profesional a los principios de jerarquía y subordinación.'}},
  {n:10, q:'La obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes:', o:{a:'En caso de fuerza mayor.', b:'En caso de peligro para la vida humana.', c:'En caso de declaración de los estados de alarma, excepción o sitio.', d:'En ningún caso.'}, correct:'d', why:{d:'El art. 5.1.d) LOFCS establece que «en ningún caso, la obediencia debida podrá amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la Constitución o a las Leyes».'}},
  {n:11, q:'En sus relaciones con la comunidad las Fuerzas y Cuerpos de Seguridad, en el ejercicio de sus funciones, se regirán por los principios de:', o:{a:'Congruencia, oportunidad y proporcionalidad en la utilización de medios a su alcance.', b:'Coordinación, oportunidad y congruencia.', c:'Congruencia, coordinación y proporcionalidad.', d:'Congruencia, oportunidad y buena fe.'}, correct:'a', why:{a:'El art. 5.2.c) LOFCS establece que las FCS se regirán al actuar por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance.'}},
  {n:12, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad deberán utilizar las armas:', o:{a:'Solamente si existe un riesgo racionalmente grave para su vida o en caso de riesgo para la seguridad ciudadana.', b:'Solamente si existe un riesgo racionalmente grave para la vida de terceros o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana.', c:'Solamente si existe un riesgo racionalmente grave para su integridad física o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana.', d:'Solamente en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o la de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana.'}, correct:'d', why:{d:'El art. 5.2.d) LOFCS señala que «solamente deberán utilizar las armas en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o las de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana».'}},
  {n:13, q:'Ante la fuga de un presunto delincuente que huye, ¿los miembros de los Cuerpos y Fuerzas de Seguridad del Estado deberán utilizar su arma de fuego?', o:{a:'No, en ningún caso.', b:'Sí, solo en supuestos de delito grave.', c:'Sí, en supuestos de delitos flagrantes.', d:'Sí, ante la comisión de cualquier delito aunque sin disparar a partes vitales del cuerpo del presunto delincuente.'}, correct:'b', why:{b:'La Instrucción de 14 de abril de 1983 de la Dirección de la Seguridad del Estado, vigente en la actualidad, establece que «solo en supuestos de delito grave» los miembros de los CFSE pueden utilizar su arma de fuego ante la fuga de un presunto delincuente.'}},
  {n:14, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad deberán identificarse debidamente como tales:', o:{a:'Antes de realizar una detención.', b:'Tras realizar una detención.', c:'Mientras realizan una detención.', d:'En el momento de efectuar una detención.'}, correct:'d', why:{d:'El art. 5.3.a) LOFCS dispone que los miembros de las FCS deberán identificarse debidamente como tales en el momento de efectuar una detención.'}},
  {n:15, q:'Cuando la actuación y el uso de las armas se ajustan estrictamente a las previsiones legales, sus consecuencias tanto en caso de lesiones como de fallecimiento de la víctima:', o:{a:'Conllevarán la exigencia de responsabilidad penal para el agente.', b:'Estarán exentas de responsabilidad penal.', c:'Conllevarán la correspondiente indemnización a la víctima.', d:'Conllevarán necesariamente la exigencia de responsabilidad civil subsidiaria del Estado.'}, correct:'b', why:{b:'Si la actuación y uso de armas se ajustan estrictamente a las previsiones legales, las consecuencias (lesiones o fallecimiento) están amparadas por la Ley y conllevan la exención de responsabilidad criminal del art. 20.7 CP (cumplimiento de un deber o ejercicio legítimo de un derecho, oficio o cargo).'}},
  {n:16, q:'Para la aplicación de la exención de responsabilidad penal al agente por utilización del arma de fuego es necesario, entre otros aspectos, que:', o:{a:'Que el agente se encuentre en el ejercicio de una función pública que le esté legalmente encomendada.', b:'Que el uso de la fuerza sea necesario y racionalmente imprescindible para el cumplimiento de la misión que ha de desempeñar.', c:'Que no se produzca una extralimitación manifiesta en el uso de la fuerza.', d:'Todas las respuestas son correctas.'}, correct:'d', why:{d:'La jurisprudencia exige todos los requisitos: 1º Que los intervinientes tengan carácter de autoridad/agentes y actúen en ejercicio de función pública legalmente encomendada; 2º Que el uso de la fuerza sea necesario y racionalmente imprescindible; 3º Que no exista extralimitación manifiesta.'}},
  {n:17, q:'No es un principio básico de actuación de los miembros de las Fuerzas y Cuerpos de Seguridad en su relación con el tratamiento de detenidos:', o:{a:'Velar por la vida e integridad física de las personas a quienes detuvieren o se encuentren bajo su custodia.', b:'Respetar el honor y la dignidad de las personas detenidas.', c:'Cumplir y observar con la debida diligencia los trámites, plazos y requisitos exigidos por el ordenamiento jurídico, cuando se proceda a la detención de una persona.', d:'Rebelar las fuentes de información que condujeron a la detención de la persona.'}, correct:'d', why:{d:'El art. 5.3 LOFCS (apartados b y c) recoge velar por vida/integridad física, respetar honor y dignidad, y cumplir trámites y plazos, pero NO hace ninguna referencia a la revelación de las fuentes de información que condujeron a la detención.'}},
  {n:18, q:'No es cierto que los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'Deberán llevar a cabo sus funciones con total dedicación.', b:'Deberán intervenir siempre en defensa de la Ley de de la seguridad ciudadana.', c:'Deberán encontrarse siempre en servicio permanente.', d:'Deberán intervenir, en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la Ley y de la seguridad ciudadana.'}, correct:'c', why:{c:'El art. 5.4 LOFCS exige total dedicación e intervención siempre que lo requiera la función, pero NO significa que los funcionarios policiales se encuentren de servicio permanentemente, sino que deben intervenir cuando lo exija el ejercicio de su función.'}},
  {n:19, q:'No es cierto que los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'Deben guardar riguroso secreto respecto a todas las informaciones que conozcan por razón o con ocasión del desempeño de sus funciones.', b:'Estarán obligados a revelar las fuentes de información relacionadas con la investigación de delitos graves.', c:'Pueden incurrir en penas de prisión por la revelación de secretos o informaciones de los que tengan conocimiento por razón del cargo y que no deban ser divulgados.', d:'Ninguna respuesta es correcta.'}, correct:'b', why:{b:'El art. 5.5 LOFCS establece que las FCS «no estarán obligadas a revelar las fuentes de información salvo que el ejercicio de sus funciones o las disposiciones de la Ley les impongan actuar de otra manera». Por tanto NO existe obligación general de revelar fuentes.'}},
  {n:20, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'Son responsables personal y directamente por los actos que en su actuación profesional lleven a cabo, infringiendo o vulnerando las normas legales.', b:'Son responsables personal e indirectamente por los actos que en su actuación profesional lleven a cabo, infringiendo o vulnerando las normas legales.', c:'Son responsables personal pero no directamente por los actos que en su actuación profesional lleven a cabo, infringiendo o vulnerando las normas legales.', d:'Son responsables personal o directamente por los actos que en su actuación profesional lleven a cabo, infringiendo o vulnerando las normas legales.'}, correct:'a', why:{a:'El art. 5.6 LOFCS dispone que los miembros de las FCS son responsables personal y directamente por los actos que en su actuación profesional llevaren a cabo infringiendo o vulnerando las normas legales, sin perjuicio de la responsabilidad patrimonial de las Administraciones Públicas.'}},
  {n:21, q:'Las disposiciones estatutarias comunes se contienen en la Ley Orgánica de Fuerzas y Cuerpos de Seguridad:', o:{a:'En el Capítulo II del Título I.', b:'En el Capítulo III del Título I.', c:'En el Capítulo III del Título II.', d:'En el Capítulo II del Título II.'}, correct:'b', why:{b:'El Capítulo III del Título I de la LO 2/1986 se rubrica «Disposiciones Estatutarias Comunes» y contiene los derechos y deberes aplicables a todos los miembros de las FCS.'}},
  {n:22, q:'Las disposiciones estatutarias comunes son aplicables:', o:{a:'Solamente al Cuerpo Nacional de Policía.', b:'Solamente al Cuerpo Nacional de Policía y a la Guardia Civil.', c:'Solamente a los miembros de las fuerzas policiales estatales y autonómicas.', d:'A todos los miembros de las Fuerzas y Cuerpos de Seguridad del Estado.'}, correct:'d', why:{d:'Las disposiciones estatutarias comunes son de aplicación universal a todas las fuerzas policiales (estatales, autonómicas o locales), junto con los principios básicos de actuación del art. 5 y los arts. 6, 7 y 8 LOFCS.'}},
  {n:23, q:'Los poderes públicos promoverán las condiciones más favorables para una adecuada promoción profesional, social y humana de los miembros de las Fuerzas y Cuerpos de Seguridad, de acuerdo con los principios de:', o:{a:'Objetividad, igualdad de oportunidades, mérito y capacidad.', b:'Publicidad en las convocatorias, igualdad de oportunidades, mérito y capacidad.', c:'Objetividad, transparencia, mérito y capacidad.', d:'Independencia, igualdad de oportunidades, mérito y capacidad.'}, correct:'a', why:{a:'El art. 6.1 LOFCS establece los principios de objetividad, igualdad de oportunidades, mérito y capacidad para la promoción profesional, social y humana de los miembros de las FCS.'}},
  {n:24, q:'La formación y perfeccionamiento de los miembros de las Fuerzas y Cuerpos de Seguridad tendrá carácter:', o:{a:'Reglado y permanente.', b:'Personal y permanente.', c:'Profesional y permanente.', d:'Contínuo y profesional.'}, correct:'c', why:{c:'El art. 6.2 LOFCS dispone que la formación y perfeccionamiento de los miembros de las FCS tendrá carácter profesional y permanente.'}},
  {n:25, q:'La fijación de los criterios de selección y formación de las Policías Locales corresponde:', o:{a:'Al Gobierno de la Nación.', b:'A las Comunidades Autónomas.', c:'A las Comunidades Autónomas o a las Entidades Locales.', d:'A las Entidades Locales.'}, correct:'b', why:{b:'Conforme al art. 39 LOFCS, corresponde a las Comunidades Autónomas fijar los criterios de selección, formación, promoción y movilidad de las Policías Locales, así como coordinar su formación profesional mediante la creación de Escuelas de Formación.'}},
  {n:26, q:'De acuerdo con el artículo 6.3 de la Ley Orgánica 2/1986 los miembros de las Fuerzas y Cuerpos de Seguridad del Estado deberán jurar o prometer:', o:{a:'Fidelidad al Rey.', b:'Cumplir fielmente las obligaciones del cargo.', c:'Acatamiento a la Constitución como norma fundamental del Estado.', d:'Fidelidad al Rey y acatamiento a la Constitución y al resto del ordenamiento jurídico.'}, correct:'c', why:{c:'El art. 6.3 LO 2/1986 impone a los miembros de todas las Fuerzas de Seguridad jurar o prometer acatamiento a la Constitución como norma fundamental del Estado.'}},
  {n:27, q:'¿A quién corresponderá dar posesión del cargo en el caso de la Policía Local?', o:{a:'Al Alcalde.', b:'Al Subdelegado del Gobierno en la Provincia.', c:'Al Secretario de la Corporación.', d:'Al Alcalde o al que por delegación de éste ostente la jefatura directa de la Policía Local.'}, correct:'d', why:{d:'Tras la derogación del art. 34.3 del Reglamento de Administración Local de 1952, corresponde dar posesión al Alcalde o Presidente de la Corporación o al Concejal que por delegación de aquél ostente la jefatura directa del personal.'}},
  {n:28, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad tendrán derecho a una remuneración justa, especificando la LOFCS en su artículo 6.4 una serie de supuestos que se deberán contemplar, ¿cuál de los siguientes no es uno de estos supuestos?', o:{a:'El nivel de formación.', b:'La movilidad por razones de servicio.', c:'El riesgo que comporta su misión.', d:'La especial peligrosidad de algunas misiones.'}, correct:'d', why:{d:'El art. 6.4 LOFCS contempla nivel de formación, régimen de incompatibilidades, movilidad por razones de servicio, dedicación, riesgo y especificidad de horarios, pero NO hace referencia a la especial peligrosidad de algunas misiones.'}},
  {n:29, q:'El régimen del horario de servicio de los miembros de las Fuerzas y Cuerpos de Seguridad se establecerá:', o:{a:'Por Ley Orgánica.', b:'Reglamentariamente.', c:'Legal o reglamentariamente.', d:'Por Ley ordinaria.'}, correct:'b', why:{b:'El art. 6.5 LOFCS dispone que «reglamentariamente se determinará su régimen de horario de servicio que se adaptará a las peculiares características de la función policial».'}},
  {n:30, q:'De acuerdo con el artículo 6.6 de la LOFCS los puestos de trabajo en las respectivas categorías se proveerán de acuerdo con los principios de:', o:{a:'Mérito, capacidad y libre concurrencia.', b:'Igualdad, capacidad y publicidad.', c:'Mérito, capacidad y antigüedad.', d:'Oportunidad, capacidad e idoneidad.'}, correct:'c', why:{c:'El art. 6.6 LOFCS establece los principios de mérito, capacidad y antigüedad. Para generar derecho a promoción interna se requiere al menos dos años de servicio activo en el grupo o subgrupo inferior.'}},
  {n:31, q:'La pertenencia a las Fuerzas y Cuerpos de Seguridad es causa de incompatibilidad:', o:{a:'Para el desempeño de cualquier otra actividad pública, salvo aquellas actividades privadas no exceptuadas de la legislación sobre incompatibilidades.', b:'Para el desempeño de cualquier actividad pública o privada, salvo aquellas actividades exceptuadas de la legislación sobre incompatibilidades.', c:'Para el desempeño de cualquier actividad privada, salvo aquellas exceptuadas de la legislación sobre incompatibilidades.', d:'Para el desempeño de cualquier actividad pública o privada salvo aquellas actividades permitidas por la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.'}, correct:'b', why:{b:'El art. 6.7 LOFCS establece que la pertenencia a las FCS es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada, salvo aquellas actividades exceptuadas de la legislación sobre incompatibilidades (Ley 53/1984).'}},
  {n:32, q:'¿Qué tipo de actividades en materia de incompatibilidades puede desempeñar cualquier miembro de las Fuerzas y Cuerpos de Seguridad?', o:{a:'Las exceptuadas de la legislación sobre incompatibilidades.', b:'Las incluidas en la legislación sobre incompatibilidades.', c:'Las actividades públicas o privadas cuya compatibilidad pueda autorizarse.', d:'Ninguna respuesta es correcta.'}, correct:'a', why:{a:'El art. 6.7 LOFCS solo permite a los policías desempeñar las actividades «exceptuadas» de la legislación de incompatibilidades (art. 19 Ley 53/1984), NO las que pudieran autorizarse como compatibles.'}},
  {n:33, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'No podrán ejercer el derecho de huelga salvo en los casos previstos reglamentariamente.', b:'No podrán ejercer en ningún caso el derecho de huelga, ni acciones substitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios.', c:'Podrán ejercer el derecho de huelga en los supuestos previstos constitucionalmente.', d:'No podrán ejercer el derecho de huelga salvo en los casos previstos legalmente siempre que no se altere el normal funcionamiento de los servicios.'}, correct:'b', why:{b:'El art. 6.8 LOFCS establece que «los miembros de las FCS no podrán ejercer en ningún caso el derecho de huelga, ni acciones sustitutivas del mismo o concertadas con el fin de alterar el normal funcionamiento de los servicios».'}},
  {n:34, q:'Los miembros de las Fuerzas y Cuerpos de seguridad tendrán a todos los efectos legales el carácter de agentes de la autoridad:', o:{a:'En los supuestos previstos reglamentariamente.', b:'En cualquier caso.', c:'En el ejercicio de sus funciones.', d:'En la situación de servicio activo.'}, correct:'c', why:{c:'El art. 7.1 LOFCS dispone que «en el ejercicio de sus funciones, los miembros de las FCS tendrán a todos los efectos legales el carácter de agentes de la autoridad».'}},
  {n:35, q:'Cuando se cometa delito de atentado empleando en su ejecución armas de fuego, explosivos u otros medios de análoga peligrosidad que puedan poner en peligro la integridad física de los miembros de las Fuerzas y Cuerpos de Seguridad, tendrán al efecto de su protección penal la consideración de:', o:{a:'Funcionario público.', b:'Autoridad.', c:'Aforado.', d:'Miembro de la seguridad del Estado.'}, correct:'b', why:{b:'El art. 7.2 LOFCS establece que cuando se cometa atentado empleando armas de fuego, explosivos u otros medios de análoga peligrosidad contra miembros de las FCS, tendrán al efecto de su protección penal la consideración de autoridad.'}},
  {n:36, q:'La Guardia Civil en el cumplimiento de las misiones de carácter militar que se le encomienden tendrá la consideración de:', o:{a:'Fuerza armada.', b:'Fuerza de orden público.', c:'Fuerza de guerra.', d:'Cuerpo de seguridad.'}, correct:'a', why:{a:'La Guardia Civil es Cuerpo de Seguridad, no Fuerza Armada, salvo excepcionalmente: cuando cumple misiones militares por encargo específico del Ministerio de Defensa o del Gobierno, guerra o estado de sitio (art. 7.3 LO 2/1986), en cuyo caso tendrá consideración de fuerza armada.'}},
  {n:37, q:'¿Qué jurisdicción será competente para conocer de los delitos que cometan los miembros de las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones?', o:{a:'La jurisdicción militar.', b:'La jurisdicción civil en cualquier caso.', c:'La jurisdicción penal en cualquier caso.', d:'La jurisdicción ordinaria.'}, correct:'d', why:{d:'El art. 8.1 LOFCS dispone que la jurisdicción ordinaria será la competente para conocer de los delitos cometidos contra y por los miembros de las FCS en el ejercicio de sus funciones, salvo los supuestos en que sea competente la jurisdicción militar (Guardia Civil con consideración de fuerza armada).'}},
  {n:38, q:'El enjuiciamiento de las infracciones penales cometidas por los miembros de las Fuerzas y Cuerpos de Seguridad cuando se trate de delitos menos graves corresponderá:', o:{a:'El conocimiento en primera instancia a los Jueces de Instrucción y la apelación a las Audiencias Provinciales.', b:'Tanto el conocimiento en primera instancia como la apelación a las Audiencias Provinciales.', c:'El conocimiento en primera instancia a las Audiencias Provinciales y la apelación a la Audiencia Nacional.', d:'El conocimiento en primera instancia a las Audiencias Provinciales y el recurso de casación ante el Tribunal Supremo.'}, correct:'a', why:{a:'Tras la STC 55/1990 y la desaparición de las faltas por la LO 1/2015, los delitos menos graves se enjuician con conocimiento en primera instancia por los Jueces de Instrucción y apelación ante las Audiencias Provinciales.'}},
  {n:39, q:'La jurisdicción competente para conocer de los delitos y delitos menos graves que cometan los miembros de las Fuerzas y Cuerpos de Seguridad en el ejercicio de sus funciones será la jurisdicción ordinaria excepto ¿qué caso?', o:{a:'Los tribunales de honor que serán competentes para conocer delitos dentro de un mismo Cuerpo.', b:'La jurisdicción militar que será aplicable a cualquier miembro de las Fuerzas y Cuerpos de Seguridad en caso de guerra.', c:'La jurisdicción militar que será aplicable a la Guardia Civil cuando tenga la consideración de fuerza armada.', d:'La jurisdicción militar que se aplicará con preferencia sobre la jurisdicción ordinaria en el caso de la Guardia Civil.'}, correct:'c', why:{c:'La LOFCS exceptúa de la jurisdicción ordinaria los supuestos en que sea competente la jurisdicción militar, que se circunscriben a la Guardia Civil cuando tenga la consideración de fuerza armada (art. 7.3).'}},
  {n:40, q:'El cumplimiento de la prisión preventiva y de las penas privativas de libertad por los miembros de las Fuerzas y Cuerpos de Seguridad se realizará:', o:{a:'En establecimientos penitenciarios militares.', b:'En establecimientos penitenciarios ordinarios, conjuntamente con el resto de presos y detenidos.', c:'En establecimientos penitenciarios ordinarios, con separación del resto de detenidos o presos.', d:'En establecimientos penitenciarios ordinarios, con separación según su grado y capacitación profesional.'}, correct:'c', why:{c:'El art. 8.2 LOFCS establece que la prisión preventiva y las penas privativas de libertad de miembros de las FCS se cumplirán en establecimientos penitenciarios ordinarios, con separación del resto de detenidos o presos. Lo mismo dispone el art. 99.2 del Reglamento Penitenciario.'}},
  {n:41, q:'La iniciación del procedimiento penal contra los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'Provocará la suspensión de las actuaciones de Jueces de Instrucción.', b:'Impedirá la incoación de expedientes gubernativos por los hechos.', c:'Impedirá la incoación de expedientes disciplinarios por los mismos hechos.', d:'No impedirá la incoación y tramitación de expedientes gubernativos o disciplinarios por los mismos hechos.'}, correct:'d', why:{d:'El art. 8.3 LOFCS señala que la iniciación de procedimiento penal contra miembros de las FCS no impedirá la incoación y tramitación de expedientes gubernativos o disciplinarios por los mismos hechos, si bien la resolución definitiva del expediente solo podrá producirse cuando la sentencia penal sea firme.'}},
  {n:42, q:'Las Fuerzas y Cuerpos de Seguridad tienen como misión constitucional:', o:{a:'Proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.', b:'El mantenimiento del orden público.', c:'Velar por el cumplimiento de las leyes y demás disposiciones del Estado.', d:'Prevenir la comisión de actos delictivos.'}, correct:'a', why:{a:'Todas las FCS tienen las mismas misiones constitucionales: proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana (art. 104.1 CE y 11.1 LOFCS).'}},
  {n:43, q:'Las funciones comunes de las Fuerzas y Cuerpos de Seguridad del Estado se ejercerán por éstas:', o:{a:'De acuerdo con una distribución material de dichas competencias.', b:'De acuerdo con una distribución territorial de dichas competencias.', c:'Bajo la autoridad de distintos Ministerios.', d:'Bajo el mando de autoridades civiles o militares.'}, correct:'b', why:{b:'El art. 11 LOFCS distribuye las funciones comunes entre el Cuerpo Nacional de Policía (capitales de provincia y términos municipales/núcleos urbanos que el Gobierno determine) y la Guardia Civil (resto del territorio nacional y mar territorial) según un criterio territorial.'}},
  {n:44, q:'¿Qué miembros de las Fuerzas y Cuerpos de Seguridad ejercen el derecho de sindicación en términos exactamente idénticos al resto de los funcionarios civiles de régimen común o general?', o:{a:'La Guardia Civil.', b:'El Cuerpo Nacional de Policía.', c:'Las policías locales.', d:'Las policías autonómicas.'}, correct:'c', why:{c:'Los miembros de las policías locales ejercen el derecho de sindicación en términos exactamente idénticos al resto de los funcionarios civiles de régimen común o general. La Guardia Civil no disfruta de ese derecho; el CNP y las policías autonómicas lo ejercen con peculiaridades.'}},
  {n:45, q:'El ejercicio del derecho de sindicación y de la acción sindical por parte de los miembros del Cuerpo Nacional de Policía tendrá como límites:', o:{a:'El respeto de los derechos fundamentales y de las libertades públicas reconocidos en la Constitución.', b:'La seguridad ciudadana y de los propios funcionarios.', c:'La garantía del secreto profesional.', d:'Todas las respuestas son correctas.'}, correct:'d', why:{d:'La LO 9/2015 (art. 8.3.a) establece como límites del derecho de sindicación del CNP: el respeto a los derechos fundamentales y libertades públicas (especialmente honor, intimidad e imagen, crédito y prestigio de las FCSE), la seguridad ciudadana y de los propios funcionarios y la garantía del secreto profesional.'}},
  {n:46, q:'Las Policías autonómicas, ¿podrán actuar fuera de su ámbito territorial?', o:{a:'No, en ningún caso.', b:'Sí, cuando ejerzan funciones de protección de autoridades públicas municipales.', c:'Sí, en situaciones de emergencia, previo requerimiento de las autoridades estatales.', d:'Sí, cuando se comunique su actuación al órgano de gobierno de la Comunidad Autónoma correspondiente.'}, correct:'b', why:{b:'El art. 42 LOFCS (modificado por la Ley 1/2003) permite a las policías autonómicas actuar fuera del ámbito territorial respectivo en situaciones de emergencia previo requerimiento de las autoridades estatales y, cuando ejerzan funciones de protección de autoridades públicas de la comunidad autónoma, previa autorización del Ministerio del Interior.'}},
  {n:47, q:'¿Cuál es la función común o básica a todos los Cuerpos de Policía?', o:{a:'El mantenimiento de la seguridad pública.', b:'La función de policía administrativa.', c:'Prevenir la comisión de actos delictivos.', d:'Velar por la protección y seguridad de altas personalidades.'}, correct:'a', why:{a:'Todos los Cuerpos de Policía cumplen la misma función básica enunciada en la Constitución y en el art. 1 LOFCS: «el mantenimiento de la seguridad pública». Esta función se desdobla en un amplio abanico de funciones específicas.'}},
  {n:48, q:'La LOFCS ¿regula de manera uniforme a todas las Policías autonómicas?', o:{a:'Sí, ya que todo su articulado es aplicable en su totalidad a cualquier Policía autonómica.', b:'Sí, ya que no hace excepciones entre las distintas Comunidades Autónomas.', c:'No, ya que todas las Policías autonómicas se crearon con posterioridad a la publicación de la LOFCS.', d:'No, ya que en sus disposiciones finales exceptúa con un trato diferenciado a algunas Policías autonómicas.'}, correct:'d', why:{d:'La LOFCS no da tratamiento uniforme: exceptúa en sus disposiciones finales a las Policías Autónomas del País Vasco, Cataluña y la Policía Foral de Navarra (regidas por sus Estatutos), sin perjuicio de los principios básicos de actuación y disposiciones estatutarias comunes.'}},
  {n:49, q:'¿Cuál de las siguientes funciones de las Policías autonómicas tiene carácter propio?', o:{a:'El mantenimiento de la seguridad pública.', b:'La función de policía administrativa derivada de la normativa estatal.', c:'La inspección de las actividades sometidas a la ordenación o disciplina de la Comunidad Autónoma, denunciando toda actividad ilícita.', d:'La función de policía judicial e investigación criminal.'}, correct:'c', why:{c:'El art. 38.1 LOFCS califica como funciones propias de las policías autonómicas: velar por el cumplimiento de las disposiciones de la CCAA, vigilancia y protección de personas/edificios de la CCAA, inspección de actividades sometidas a la disciplina de la CCAA y uso de la coacción para ejecución forzosa.'}},
  {n:50, q:'¿Cuál de las siguientes funciones de las Policías autonómicas no se ejercerá en régimen de colaboración con las Fuerzas y Cuerpos de Seguridad del Estado?', o:{a:'El uso de la coacción en orden a la ejecución forzosa de los actos o disposiciones de la propia Comunidad Autónoma.', b:'El mantenimiento del orden público en grandes concentraciones humanas.', c:'La vigilancia de los espacios públicos.', d:'La participación en las funciones de policía judicial.'}, correct:'a', why:{a:'El uso de la coacción en orden a la ejecución forzosa de los actos o disposiciones de la propia CCAA es una función PROPIA de la policía autonómica (art. 38.1.d LOFCS), no de colaboración. Las funciones de colaboración están en el art. 38.2 (cumplimiento Leyes del Estado, policía judicial, vigilancia espacios públicos, orden público en grandes concentraciones).'}},
  {n:51, q:'Las Corporaciones Locales ¿participan en el mantenimiento de la seguridad pública?', o:{a:'No, ya que de acuerdo con el artículo 1 de la LOFCS la seguridad pública es competencia exclusiva del Estado.', b:'No, ya que de acuerdo con el artículo 1 de la LOFCS el mantenimiento de la seguridad pública corresponde al Gobierno de la Nación.', c:'Sí, ya que dentro del término municipal el mantenimiento de la seguridad pública es competencia exclusiva de los Municipios.', d:'Sí, en los términos establecidos en la Ley Reguladora de las Bases del Régimen Local y en el marco de la LOFCS.'}, correct:'d', why:{d:'El art. 1.3 LOFCS dispone que las Corporaciones Locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley Reguladora de las Bases del Régimen Local y en el marco de la LOFCS.'}},
  {n:52, q:'La LOFCS reconoce la posibilidad de creación de cuerpos de policía propios:', o:{a:'A las Corporaciones Locales.', b:'A las Diputaciones Provinciales.', c:'A los Municipios.', d:'A las Entidades Locales supramunicipales.'}, correct:'c', why:{c:'El art. 51.1 LOFCS reconoce solamente a los municipios la posibilidad de crear cuerpos de policía propios. El TC ha rechazado la creación de cuerpos supramunicipales de policía local.'}},
  {n:53, q:'¿Se reconoce en la LOFCS la creación de cuerpos de policía provinciales?', o:{a:'Sí, y así lo ha hecho la provincia de Alava en el caso de los Miñones.', b:'Sí, en el caso de provincias cuyo territorio esté integrado por varias islas.', c:'Sí en el caso que dependan de una Diputación Foral.', d:'No.'}, correct:'d', why:{d:'La provincia carece de la posibilidad de crear cuerpos de policía. La legislación de régimen local no prevé competencia provincial en materia de policía local. Los cuerpos provinciales históricos (Miñones, Miqueletes) se refundieron en la Ertzaintza.'}},
  {n:54, q:'En los municipios donde no exista policía municipal:', o:{a:'No se ejercerán las funciones que la Ley reserva a los Cuerpos de Policía Local.', b:'Las funciones propias de la policía local podrán realizarse por medio de Guardias de Seguridad Privados.', c:'Las funciones propias de la policía local podrán realizarse por medio de una empresa concesionaria.', d:'Los cometidos de la policía local serán ejercidos por el personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones.'}, correct:'d', why:{d:'El art. 51.2 LOFCS dispone que, en municipios sin cuerpo de policía propio, las funciones serán asumidas «por el personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones, con la denominación de guardas, vigilantes, agentes, alguaciles o análogos».'}},
  {n:55, q:'¿Podrán los Cuerpos de Policía Local actuar fuera del ámbito territorial del municipio respectivo?', o:{a:'No, en ningún caso.', b:'Sí, cuando ejerzan funciones de protección de autoridades públicas autonómicas.', c:'Sí, en situaciones de emergencia, previo requerimiento de las autoridades competentes.', d:'Sí, cuando se comunique su actuación al órgano de gobierno de la Comunidad Autónoma correspondiente.'}, correct:'c', why:{c:'El art. 51.3 LOFCS permite actuar fuera del municipio en situaciones de emergencia y previo requerimiento de las autoridades competentes. También en protección de autoridades de las Corporaciones Locales con autorización del Ministerio del Interior o de la CCAA.'}},
  {n:56, q:'¿Son aplicables los principios básicos de actuación y las disposiciones estatutarias comunes reguladas en el Título I de la LOFCS a los Cuerpos de Policía Local?', o:{a:'Sí, aunque con carácter supletorio.', b:'Sí.', c:'No.', d:'Sí, los principios básicos de actuación pero no las disposiciones estatutarias comunes.'}, correct:'b', why:{b:'El art. 52 LOFCS extiende a la policía local el régimen estatutario contenido en los arts. 5 y siguientes, por lo que los principios básicos de actuación y las disposiciones estatutarias comunes le son plenamente aplicables.'}},
  {n:57, q:'Los funcionarios de la policía local ¿están sujetos al deber de vestir uniforme?', o:{a:'Sí, en todo caso.', b:'No.', c:'Sí, salvo dispensa para casos concretos del Subdelegado del Gobierno.', d:'Sí, si así lo autoriza el Alcalde de acuerdo con lo dispuesto en la LOFCS.'}, correct:'c', why:{c:'El art. 53.3 LOFCS en conexión con el art. 41.3 establece que los funcionarios de policía local tienen el deber de vestir uniforme, salvo dispensa para casos concretos del Subdelegado del Gobierno (o Delegado del Gobierno en CCAA uniprovinciales).'}},
  {n:58, q:'La decisión sobre qué tipos de servicios se prestan con armas en los Cuerpos de la Policía Local corresponde:', o:{a:'Al Subdelegado del Gobierno en la Provincia.', b:'Al Alcalde.', c:'Al Consejo de Gobierno de la Comunidad Autónoma.', d:'Al mando de mayor grado del Cuerpo de Policía Local.'}, correct:'b', why:{b:'Según la STC 81/1993, la decisión sobre qué tipos de servicios de la Policía Local se prestan con armas corresponde al Alcalde, por línea jerárquica, sin que ello suponga invasión de competencias estatales.'}},
  {n:59, q:'¿Qué legislación determina el tipo de armas a utilizar por las Policías Locales?', o:{a:'La legislación estatal.', b:'La legislación estatal y la autonómica.', c:'La legislación autonómica y la de las entidades locales.', d:'La legislación de las entidades locales.'}, correct:'b', why:{b:'El TC admite que la legislación autonómica regule el tipo de armas que pueden llevar las Policías Locales, marcando criterios para marcas y modelos, siempre dentro de los tipos permitidos por la legislación del Estado (competencia estatal en materia de armas).'}},
  {n:60, q:'Las funciones propias de los Cuerpos de Policía Local se regulan con carácter general:', o:{a:'En las leyes de coordinación de las Comunidades Autónomas.', b:'En los reglamentos municipales de la Policía Local.', c:'En la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.', d:'En la legislación básica de régimen local.'}, correct:'c', why:{c:'La LO 2/1986 de Fuerzas y Cuerpos de Seguridad es la primera norma que aborda una regulación general de todos los Cuerpos de Policía y por primera vez hace una regulación completa de las funciones de la Policía Local en su art. 53.'}},
  {n:61, q:'Dentro de las funciones que podrán ejercer los Cuerpos de Policía Local la LOFCS señala:', o:{a:'La protección de las autoridades de las corporaciones locales.', b:'La protección de las autoridades municipales.', c:'La protección de cualquier autoridad.', d:'La protección de las autoridades de las diputaciones provinciales.'}, correct:'a', why:{a:'El art. 53.1.a) LOFCS atribuye en exclusiva a la policía local «proteger a las autoridades de las corporaciones locales». Es un supuesto de autodefensa de la Administración local.'}},
  {n:62, q:'De acuerdo con el artículo 53.1.a) de la LOFCS corresponde a la Policía Local la vigilancia y custodia:', o:{a:'De los edificios e instalaciones de las corporaciones locales.', b:'De la casa consistorial.', c:'De los bienes de la Administración local.', d:'Del patrimonio de la Administración local.'}, correct:'a', why:{a:'El art. 53.1.a) LOFCS hace referencia a la vigilancia o custodia de los edificios e instalaciones de las corporaciones locales. La protección debe extenderse principalmente a los bienes demaniales pero también a los patrimoniales.'}},
  {n:63, q:'Corresponde a la Policía Local ordenar, señalizar y dirigir el tráfico:', o:{a:'En todo el término municipal.', b:'En el casco urbano.', c:'En el suelo urbano y no urbanizable.', d:'En el centro de la ciudad y en su periferia.'}, correct:'b', why:{b:'El art. 53.1.b) LOFCS atribuye en exclusiva a la Policía Local la ordenación del tráfico de vehículos y personas dentro del casco urbano. Fuera del casco urbano, la competencia primaria es de la Guardia Civil (art. 12.1.c LOFCS).'}},
  {n:64, q:'¿Es competente la Policía Local para ordenar, señalizar y dirigir el tráfico en las travesías?', o:{a:'Sí, si disponen de entramado de calles a ambos márgenes.', b:'Sí, ya que éstas en toda su longitud forman parte del casco urbano.', c:'Sí, si legalmente tienen la consideración de travesía.', d:'No porque la vigilancia del tráfico en estas vías corresponde a la Guardia Civil.'}, correct:'c', why:{c:'La Ley General de Carreteras (art. 37) define travesía como la parte de tramo urbano con edificaciones consolidadas en al menos 2/3 de su longitud y entramado de calles en al menos uno de sus márgenes. Si reúne legalmente esa consideración, la Policía Local es competente.'}},
  {n:65, q:'La instrucción de atestados por accidentes de tráfico dentro del casco urbano es función de:', o:{a:'La Policía Local.', b:'La Guardia Civil.', c:'La Guardia Civil en el caso de las travesías.', d:'El Cuerpo de Policía que hubiese iniciado las primeras actuaciones.'}, correct:'a', why:{a:'El art. 53.1.c) LOFCS atribuye a la Policía Local «instruir atestados por accidentes de circulación dentro del casco urbano». Es competencia exclusiva donde exista este cuerpo.'}},
  {n:66, q:'La LOFCS atribuye a Policía Local funciones de policía administrativa:', o:{a:'En lo relativo a las disposiciones normativas estatales.', b:'En lo relativo a las disposiciones normativas autonómicas.', c:'En lo relativo a las ordenanzas, bandos y demás disposiciones municipales dentro del ámbito de su competencia.', d:'En lo relativo a las ordenanzas, bandos y demás disposiciones municipales, autonómicas o estatales que tengan relación con sus competencias.'}, correct:'c', why:{c:'El art. 53.d) LOFCS atribuye a la Policía Local funciones de policía administrativa, en lo relativo a las ordenanzas, bandos y demás disposiciones municipales dentro del ámbito de su competencia.'}},
  {n:67, q:'La participación de la Policía Local en las funciones de policía judicial se realizará:', o:{a:'Mediante la creación de unidades especializadas.', b:'Solamente en caso de instruir atestados por accidentes de tráfico dentro del casco urbano.', c:'Dependiendo funcionalmente de las Fuerzas y Cuerpos de Seguridad del Estado.', d:'Con carácter colaborador de Unidades de Policía Judicial de las Fuerzas y Cuerpos de Seguridad del Estado.'}, correct:'d', why:{d:'El art. 29.9 LOFCS prevé que la policía local colabore en materia de policía judicial con las Unidades especializadas de la Guardia Civil y la Policía Nacional, sin crear unidades especializadas propias. Cuando actúe en funciones de policía judicial dependerá funcionalmente de la autoridad judicial y del Ministerio Fiscal.'}},
  {n:68, q:'La Policía Local no está obligada a prestar auxilio en los casos de:', o:{a:'Accidentes.', b:'Catástrofes.', c:'Calamidades públicas.', d:'Conflictos privados entre particulares.'}, correct:'d', why:{d:'El art. 53.1.f) LOFCS impone prestar auxilio en accidentes, catástrofes o calamidades públicas. En cuanto a conflictos privados entre particulares (art. 53.1.i), la función es solo «cooperar en la resolución», y únicamente cuando sean requeridos, no como auxilio obligatorio.'}},
  {n:69, q:'La cooperación en la resolución de los conflictos privados es función de la Policía Local:', o:{a:'Pudiendo actuar de oficio.', b:'Cuando sean requeridos para ello.', c:'A instancias del Ministerio Fiscal.', d:'Ejerciendo una función formal de arbitraje.'}, correct:'b', why:{b:'El art. 53.1.i) LOFCS in fine establece como condición que «sean requeridos para ello». Se trata de una actividad informal de arbitraje, no de actuación de oficio.'}},
  {n:70, q:'La prestación de auxilio por parte de la Policía Local, en los casos de accidente, catástrofe o calamidad pública se realizará:', o:{a:'En la ejecución de los planes de protección civil.', b:'Dando cuenta a las Fuerzas y Cuerpos de Seguridad del Estado.', c:'Con carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado.', d:'Dependiendo funcionalmente de Jueces y Magistrados.'}, correct:'a', why:{a:'El art. 53.1.f) LOFCS especifica que la prestación de auxilio se realizará «en la forma prevista en las Leyes, en la ejecución de los planes de protección civil». Es responsabilidad de las corporaciones locales elaborar y aprobar su propio Plan.'}},
  {n:71, q:'La vigilancia de los espacios públicos por parte de la Policía Local es una función que se ejerce:', o:{a:'En colaboración con las Fuerzas y Cuerpos de Seguridad del Estado.', b:'Siempre que no entre en conflicto con las policías estatales, a quienes corresponde la competencia primaria en la materia.', c:'Como función propia y exclusiva de la Policía Local.', d:'Bajo la dirección de las Fuerzas y Cuerpos de Seguridad del Estado.'}, correct:'b', why:{b:'La Policía Local (art. 53.1.h LOFCS y 25.2.a LBRL) puede realizar cierta labor autónoma de vigilancia en lugares públicos, siempre que no entre en conflicto con las policías estatales, a quienes corresponde la competencia primaria en la materia.'}},
  {n:72, q:'El mantenimiento del orden en las grandes concentraciones humanas será función de la Policía Local:', o:{a:'En cualquier caso.', b:'Cuando sea requerida para ello.', c:'Bajo la dirección del Alcalde.', d:'Ejerciendo funciones de mediación y arbitraje.'}, correct:'b', why:{b:'Según el art. 53.1.h) LOFCS, la Policía Local solo actúa en el mantenimiento del orden en grandes concentraciones cuando sea requerida para ello. Está obligada a cooperar con las policías estatales y autonómicas, bajo la dirección última de éstas.'}},
  {n:73, q:'¿Qué funciones de la Policía Local deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado?', o:{a:'Las que impliquen el ejercicio de la coacción directa.', b:'Las que requieran el uso de armas.', c:'Las ejercidas como policía judicial.', d:'De las que se desprenda un grave riesgo para la seguridad ciudadana.'}, correct:'c', why:{c:'El art. 53.2 LOFCS dispone que las actuaciones de la policía local en funciones de policía judicial (instruir atestados por accidentes y efectuar diligencias de prevención) deberán ser comunicadas a las Fuerzas y Cuerpos de Seguridad del Estado competentes.'}},
  {n:74, q:'¿Qué tipo de entidades locales podrán crear cuerpos de funcionarios para ordenar, señalizar y dirigir el tráfico en el casco urbano sin que se integren en las Fuerzas y Cuerpos de Seguridad?', o:{a:'Los municipios.', b:'Los municipios de gran población.', c:'Las mancomunidades de municipios.', d:'Las áreas metropolitanas.'}, correct:'b', why:{b:'El art. 53.3 LOFCS (modificado por la LO 19/2003) permite a los municipios de gran población crear, por el Pleno de la Corporación, Cuerpos de funcionarios (agentes de movilidad) para el ejercicio exclusivo de ordenar, señalizar y dirigir el tráfico en el casco urbano.'}},
  {n:75, q:'¿Están facultados los agentes de movilidad para efectuar una detención y portar armas?', o:{a:'Sí, ya que tienen la consideración de agentes de la autoridad.', b:'No.', c:'Sí, ya que le son aplicables los principios básicos de actuación de las Fuerzas y Cuerpos de Seguridad.', d:'No, si así se establece por delegación del órgano competente.'}, correct:'b', why:{b:'Los agentes de movilidad son agentes de la autoridad solo cuando están de servicio (a diferencia de un policía). NO tienen autoridad para efectuar una detención legalmente ni para portar un arma (de mano, de fuego o esposas).'}},
  {n:76, q:'Los agentes de movilidad se regirán:', o:{a:'Por las normas contenidas en el Estatuto Básico del Empleado Público.', b:'Las normas aplicables a las Fuerzas y Cuerpos de Seguridad del Estado.', c:'Las normas aplicables a las policías autonómicas.', d:'Las normas aplicables a las policías locales.'}, correct:'a', why:{a:'El art. 53.3 LOFCS remite a la Ley 30/1984 (prácticamente derogada por la Ley 7/2007, Estatuto Básico del Empleado Público, hoy TRLEBEP). Por tanto, los agentes de movilidad se rigen por el EBEP y normas de desarrollo.'}},
  {n:77, q:'Los agentes de movilidad estarán subordinados:', o:{a:'A los miembros de las Fuerzas y Cuerpos de Seguridad del Estado.', b:'A los miembros de los respectivos cuerpos de Policía Local.', c:'A las órdenes del Subdelegado del Gobierno en la Provincia.', d:'A la Junta de Gobierno Local.'}, correct:'b', why:{b:'El art. 53.3 in fine LOFCS indica que los agentes de movilidad no se integrarán en las FCS, y en el ejercicio de sus funciones tendrán la consideración de agentes de la autoridad, subordinados a los miembros de los respectivos Cuerpos de Policía Local.'}},
  {n:78, q:'¿Quién está facultado para la creación de los cuerpos de agentes de movilidad en los municipios de gran población?', o:{a:'El Alcalde.', b:'La Junta de Gobierno Local.', c:'El Pleno de la Corporación.', d:'El Consejo de Gobierno de la Comunidad Autónoma.'}, correct:'c', why:{c:'El art. 53.3 LOFCS atribuye al Pleno de la Corporación la creación de los cuerpos de agentes de movilidad. El mismo órgano aprueba el Reglamento que regulará criterios de actuación, funcionamiento y organización.'}},
  {n:79, q:'¿Cuál será el órgano competente para establecer las formas y procedimientos de colaboración entre los miembros de las Fuerzas y Cuerpos de Seguridad en su ámbito territorial?', o:{a:'La Junta de Gobierno Local.', b:'La Junta Local de Seguridad.', c:'El Pleno de la Corporación.', d:'El Alcalde.'}, correct:'b', why:{b:'El art. 54.1 LOFCS dispone que en los municipios con cuerpo de policía propio podrá constituirse una Junta Local de Seguridad, órgano colegiado competente para establecer las formas y procedimientos de colaboración entre los miembros de las FCS en su ámbito territorial.'}},
  {n:80, q:'La presidencia de la Junta Local de Seguridad corresponderá:', o:{a:'En todo caso al Alcalde.', b:'Al Subdelegado del Gobierno en la Provincia.', c:'Al Alcalde, salvo que concurriera a sus sesiones el Subdelegado del Gobierno en la Provincia, en cuyo caso, la presidencia será compartida con éste.', d:'Al Alcalde, salvo que concurriera a sus sesiones el Subdelegado del Gobierno en la Provincia, en cuyo caso, la presidencia corresponderá a éste último.'}, correct:'c', why:{c:'El art. 54.2 in fine LOFCS establece que la presidencia corresponderá al alcalde, salvo que concurriera a sus sesiones el Subdelegado del Gobierno (anteriormente Gobernador Civil), en cuyo caso, la presidencia será compartida con éste.'}}
];
